package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.User;import com.casystem.onboarding.repository.UserRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.regex.Pattern;
@RestController @RequestMapping("/api/account") @CrossOrigin(origins="*") public class AccountController{
 private final UserRepository users;private final TokenService tokens;private final PasswordEncoder encoder;private final AuditService audit;private static final Pattern NAME=Pattern.compile("^[\\p{L} .'-]{2,80}$");
 public AccountController(UserRepository u,TokenService t,PasswordEncoder e,AuditService a){users=u;tokens=t;encoder=e;audit=a;}
 private User me(String h){return users.findById(tokens.userId(h)).filter(u->!u.isDeleted()).orElseThrow();}
 @PutMapping("/name") public Map<String,String> name(@RequestHeader("Authorization")String h,@RequestBody Map<String,String>x,HttpServletRequest req){String n=x.getOrDefault("name","").trim();if(!NAME.matcher(n).matches())throw new IllegalArgumentException("Nombre inválido");User u=me(h);u.setName(n);users.save(u);audit.log(u.getId(),"Perfil actualizado: nombre",req.getRemoteAddr());return Map.of("message","Nombre actualizado","name",n);}
 @PutMapping("/password") public Map<String,String> password(@RequestHeader("Authorization")String h,@RequestBody Map<String,String>x,HttpServletRequest req){User u=me(h);String old=x.getOrDefault("currentPassword","");String np=x.getOrDefault("newPassword","");if(!encoder.matches(old,u.getPassword()))throw new IllegalArgumentException("La contraseña actual no es correcta");if(np.length()<8||!np.matches(".*[A-Za-z].*")||!np.matches(".*\\d.*"))throw new IllegalArgumentException("La nueva contraseña debe tener al menos 8 caracteres, letras y números");u.setPassword(encoder.encode(np));users.save(u);audit.log(u.getId(),"Contraseña cambiada",req.getRemoteAddr());return Map.of("message","Contraseña actualizada");}
}
